import { useCallback, useMemo, useState } from 'react';
import { JxChip, JxTagInput } from '@jinx-ui/react';

export interface ArticleTagPickerProps {
  value?: string[];
  defaultValue?: string[];
  onChange?: (tags: string[]) => void;
  label?: string;
  placeholder?: string;
  emptyText?: string;
}

export default function ArticleTagPicker({
  value,
  defaultValue = [],
  onChange,
  label = 'Теги статьи',
  placeholder = 'Введите тег и нажмите Enter',
  emptyText = 'Пока ни одного тега. Наберите слово и нажмите Enter, чтобы добавить.',
}: ArticleTagPickerProps) {
  const [internalTags, setInternalTags] = useState<string[]>(defaultValue);
  const tags = value ?? internalTags;

  const commit = useCallback(
    (next: string[]) => {
      if (value === undefined) setInternalTags(next);
      onChange?.(next);
    },
    [onChange, value],
  );

  const handleValueChange = useCallback(
    (next: string[]) => {
      const seen = new Set<string>();
      const normalized = next.reduce<string[]>((acc, raw) => {
        const tag = raw.trim();
        const key = tag.toLowerCase();
        if (tag && !seen.has(key)) {
          seen.add(key);
          acc.push(tag);
        }
        return acc;
      }, []);
      commit(normalized);
    },
    [commit],
  );

  const removeTag = useCallback(
    (tag: string) => {
      commit(tags.filter((item) => item !== tag));
    },
    [commit, tags],
  );

  const counter = useMemo(
    () => (tags.length === 1 ? '1 тег' : `${tags.length} тегов`),
    [tags.length],
  );

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: '12px' }}>
      <div style={{ display: 'flex', flexDirection: 'column', gap: '6px' }}>
        <span
          style={{
            fontFamily: 'var(--jx-font-sans)',
            fontSize: '14px',
            fontWeight: 600,
            color: 'var(--jx-text)',
          }}
        >
          {label}
        </span>
        <JxTagInput
          ariaLabel={label}
          placeholder={placeholder}
          value={tags}
          onValueChange={handleValueChange}
        />
      </div>

      {tags.length === 0 ? (
        <p
          style={{
            margin: 0,
            fontFamily: 'var(--jx-font-sans)',
            fontSize: '13px',
            lineHeight: 1.5,
            color: 'var(--jx-text-2)',
          }}
        >
          {emptyText}
        </p>
      ) : (
        <div style={{ display: 'flex', flexDirection: 'column', gap: '8px' }}>
          <span
            style={{
              fontFamily: 'var(--jx-font-sans)',
              fontSize: '13px',
              color: 'var(--jx-text-2)',
            }}
          >
            {counter}
          </span>
          <div
            style={{
              display: 'flex',
              flexWrap: 'wrap',
              gap: '8px',
              maxWidth: '100%',
            }}
          >
            {tags.map((tag) => (
              <JxChip key={tag} removable onRemove={() => removeTag(tag)}>
                {tag}
              </JxChip>
            ))}
          </div>
        </div>
      )}
    </div>
  );
}

